anManage): ?><button class="icon-button small" data-delete-document="<?= (int)$document['id'] ?>" title="Supprimer"><i data-lucide="trash-2"></i></button><?php endif; ?></div></article><?php endforeach; ?></div></div><div class="detail-pane" data-detail-pane="deliveries"><?php if(!$vehicle['deliveries']): ?><div class="driver-empty"><i data-lucide="route"></i><strong>Aucune livraison enregistrée</strong><p>Les futures livraisons apparaîtront ici.</p></div><?php else: ?><div class="professional-table-wrap"><table class="professional-table"><thead><tr><th>Référence</th><th>Client</th><th>Itinéraire</th><th>Chauffeur</th><th>Début</th><th>Distance</th><th>Statut</th></tr></thead><tbody><?php foreach($vehicle['deliveries'] as $delivery): ?><tr><td><strong><?= htmlspecialchars($delivery['delivery_reference'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars($delivery['client_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($delivery['origin'].' → '.$delivery['destination'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($delivery['driver_name']?:'—',ENT_QUOTES,'UTF-8') ?></td><td><?= $delivery['started_at']?date('d/m/Y H:i',strtotime($delivery['started_at'])):'—' ?></td><td><?= $delivery['distance_km']?$delivery['distance_km'].' km':'—' ?></td><td><?= View::partial('components/status-badge',['status'=>$delivery['status']]) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><div class="detail-pane" data-detail-pane="history"><ol class="history-timeline"><?php foreach($vehicle['history'] as $event): ?><li><span><i data-lucide="<?= strpos($event['action'],'document')===0?'file-text':($event['action']==='created'?'plus':($event['action']==='deactivated'?'archive':'pencil')) ?>"></i></span><div><strong><?= htmlspecialchars($event['description'],ENT_QUOTES,'UTF-8') ?></strong><p><?= htmlspecialchars($event['user_name']?:'Système',ENT_QUOTES,'UTF-8') ?> · <?= date('d/m/Y à H:i',strtotime($event['created_at'])) ?></p></div></li><?php endforeach; ?></ol></div></section>
