ept="application/pdf,image/jpeg,image/png,image/webp" required></label><div class="modal-actions"><button type="button" class="button button-secondary" data-modal-close>Annuler</button><button class="button button-primary" type="submit">Ajouter le document</button></div></form></section></div><?php endif; ?>
